UPDATE studio_backup_snapshots SET snapshot=snapshot||'egan hunting Captain Blackheart\nMet Kaelen at Sunstone Coast\nJoined forces with Kaelen\nReturned to Moonwoodvail with Kaelen\nTrained under Silas"},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/808d3a77-faab-458d-9d54-715ac887bb40/portrait/1790363965860-sax-character-portrait.png","relationships":{"allies":"Kaelen Thorne\nAsha\nKeno\nMali\nUmbra Crew","rivals":"Zafir\nRico","enemies":"Captain Blackheart\nAzure Fleet","mentors":"Silas\nMama Eve","parents":"","partner":"","children":"","siblings":"","worldConnections":"Moonwoodvail\nSunstone Coast\nAethelgard","relationshipNotes":"Silas is Sax''s uncle and primary Voodoo mentor, taking custody of him after the destruction of his family. Kaelen becomes Sax''s first close companion after they fight Blackheart''s thugs together near the Sunstone Coast, and Sax becomes fiercely protective of him. Sax has an explosive rivalry with Zafir, whose teasing and mini-form antics regularly provoke him. Asha, Keno, Mali, and Rico belong to Sax''s childhood Moonwoodvail peer group."},"spoiler_level":"private","race_record_id":"baaf3d0d-afe5-4ad3-92e2-14dbe7cbd5e0","realm_record_id":"63782818-208e-4e9b-a57c-9c33daba0589","workflow_status":"draft","family_record_id":"0b04c5a0-22fd-4442-a86d-eea0aeb15514","faction_record_id":"bd19189f-d8ba-4190-af7a-4c9df16e50c9"},{"id":"34b16e35-6625-4143-b97b-a3b628d60617","name":"Calliope","media":{"tbdFields":"Mother\nBirth date\nHeight\nWeight\nDominant hand\nOccupation\nWeapons\nSignature techniques\nWeaknesses\nAbility limitations\nPartner\nStory role\nStory arc","canonLocks":"Female\nLate 20s\nKing Kaelo''s child\n4C hair\nThick long locs\nLioness/Dire Wolf hybrid\nTawny-gold werebeast coat\nDire wolf-like legs and paws\nFeminine werebeast form\nNo male lion mane\nMoonwood Vail","galleryUrl":"","mediaNo